files.archive/extract.py:
"""Unpacking a tar archive into a folder without letting it reach outside that folder.

Archives reach us from two places, plugin bundles (plugins/installer.py) and user backups (backups/restore.py), and
neither is trusted. safe_extract checks every member before it writes anything, so an archive it refuses leaves
the destination as it was. The check follows links the way the system will, including links that earlier members
of the same archive create.
"""
import os
import shutil
import tarfile

from . import limits, paths
from .errors import UnsafeArchive

FILE_MODE = 0o644
EXEC_MODE = 0o755
MAX_HOPS = 40  # links followed on one path before it counts as a loop


def safe_extract(tar_path, dest):
    """Extract the tar at tar_path into the existing folder dest; return the member names, in archive order.

    Regular files, folders and symbolic links are extracted, and a link may point only inside dest. A member that
    would land outside dest, a link that points outside it, a name listed twice, any other kind of member or an
    archive over the size limits raises UnsafeArchive, and then nothing has been written."""
    root = os.path.realpath(dest)
    if not os.path.isdir(root):
        raise NotADirectoryError(dest)
    try:
        tar = tarfile.open(tar_path)
    except tarfile.TarError as e:
        raise UnsafeArchive(f"not a tar archive: {e}") from None
    with tar:
        try:
            members = tar.getmembers()
        except tarfile.TarError as e:
            raise UnsafeArchive(f"not a readable tar archive: {e}") from None
        limits.check(members)
        actions = plan_members(root, members)
        made = []
        try:
            for action in actions:
                perform(tar, root, action, made)
        except BaseException as e:
            undo(made)
            if isinstance(e, tarfile.TarError):
                raise UnsafeArchive(f"not a readable tar archive: {e}") from None
            raise
    return [paths.clean_name(m.name) for m in members]


def plan_members(root, members):
    """The actions that write the archive, in order, or UnsafeArchive. Nothing is written here.

    An action is ("dir", parts), ("link", parts, target) or ("file", parts, member), where parts is the path under
    root with no link left in it. Links are checked last, against the destination as the whole archive leaves it."""
    tree = _Tree(root)
    seen, links = set(), []
    for member in members:
        name = paths.clean_name(member.name)
        if name in seen:
            raise UnsafeArchive(f"{name} is listed twice")
        seen.add(name)
        parts = name.split("/")
        if member.issym():
            if not paths.is_link_text(member.linkname):
                raise UnsafeArchive(f"{name} links to an absolute path or to a name that isn't a POSIX path")
        elif member.islnk():
            raise UnsafeArchive(f"{name} is a hard link")
        elif not (member.isfile() or member.isdir()):
            raise UnsafeArchive(f"{name} is a device, a FIFO or another special file")
        if member.isdir():
            tree.walk(parts, name, create=True)
            continue
        folder = tree.walk(parts[:-1], name, create=True)
        here = folder + (parts[-1],)
        if tree.kind(here) is not None:
            raise UnsafeArchive(f"{name} is already there")
        if member.issym():
            tree.added[here] = ("link", member.linkname)
            tree.actions.append(("link", here, member.linkname))
            links.append((name, here))
        else:
            tree.added[here] = ("file",)
            tree.actions.append(("file", here, member))
    for name, here in links:
        tree.walk(list(here), name, create=False)  # raises UnsafeArchive if the link leads outside root
    return tree.actions


class _Tree:
    """The destination as the plan leaves it: what is already in it, plus what the archive has added so far."""

    def __init__(self, root):
        self.root = root
        self.added = {}  # parts -> ("dir",) | ("file",) | ("link", target)
        self.actions = []

    def kind(self, parts):
        if parts in self.added:
            return self.added[parts]
        if not parts:
            return ("dir",)
        real = os.path.join(self.root, *parts)
        if os.path.islink(real):
            return ("link", os.readlink(real))
        if os.path.isdir(real):
            return ("dir",)
        if os.path.lexists(real):
            return ("file",)
        return None

    def walk(self, parts, name, create):
        """The folder the path parts leads to under root, following each link on the way as the system would, so
        that the result has no link in it. With create, a missing folder is planned for each part (but never through
        a link). UnsafeArchive when the path leads outside root or runs through something that isn't a folder."""
        out, hops, pending = (), 0, list(parts)
        while pending:
            part = pending.pop(0)
            if part in ("", "."):
                continue
            if part == "..":
                if not out:
                    raise UnsafeArchive(f"{name} leads outside the destination")
                out = out[:-1]
                continue
            here = out + (part,)
            entry = self.kind(here)
            if entry is not None and entry[0] == "link":
                hops += 1
                if hops > MAX_HOPS or entry[1].startswith("/"):
                    raise UnsafeArchive(f"{name} runs through a link that leads outside the destination")
                pending = entry[1].split("/") + pending
                continue
            if create:
                if entry is None:
                    if hops:
                        raise UnsafeArchive(f"{name} runs through a link to a folder that isn't there yet")
                    self.added[here] = ("dir",)
                    self.actions.append(("dir", here))
                elif entry[0] != "dir":
                    raise UnsafeArchive(f"{name} runs through {part}, which isn't a folder")
            out = here
        return out


def perform(tar, root, action, made):
    """Carry out one planned action; made records what was created, so undo can take it back."""
    kind, parts = action[0], action[1]
    path = os.path.join(root, *parts)
    if kind == "dir":
        os.mkdir(path)
        made.append(("dir", path))
    elif kind == "link":
        os.symlink(action[2], path)
        made.append(("link", path))
    else:
        member = action[2]
        with tar.extractfile(member) as src, open(path, "xb") as out:
            made.append(("file", path))
            shutil.copyfileobj(src, out)
        os.chmod(path, EXEC_MODE if member.mode & 0o100 else FILE_MODE)


def undo(made):
    """Remove what perform created, newest first, so the destination is as it was."""
    for kind, path in reversed(made):
        try:
            if kind == "dir":
                os.rmdir(path)
            else:
                os.unlink(path)
        except OSError:
            pass

