"""MANIFEST.json, written at the root of every backup: the sha256 of each file and the target of each link."""
import hashlib
import json
import os

from archive import UnsafeArchive, paths
from archive.pack import walk

NAME = "MANIFEST.json"


class ManifestMismatch(ValueError):
    pass


def sha256(path):
    digest = hashlib.sha256()
    with open(path, "rb") as f:
        for block in iter(lambda: f.read(1 << 16), b""):
            digest.update(block)
    return digest.hexdigest()


def build(root):
    """{"files": {path: sha256}, "links": {path: target}} for the tree under root, paths relative and POSIX."""
    files, links = {}, {}
    for rel, path in walk(root):
        if rel == NAME:
            continue
        if os.path.islink(path):
            links[rel] = os.readlink(path)
        elif os.path.isfile(path):
            files[rel] = sha256(path)
    return {"files": files, "links": links}


def dumps(manifest):
    return json.dumps(manifest, indent=2, sort_keys=True, ensure_ascii=False) + "\n"


def under(root, rel):
    """The path rel names under root. The manifest comes from the archive, so rel is checked like a member name:
    ManifestMismatch rather than a path that reaches outside the backup."""
    try:
        return os.path.join(root, *paths.clean_name(rel).split("/"))
    except UnsafeArchive:
        raise ManifestMismatch(f"{rel} isn't a path inside the backup") from None


def verify(root, manifest):
    """ManifestMismatch unless every file and link the manifest lists is under root as it says."""
    for rel, digest in manifest.get("files", {}).items():
        path = under(root, rel)
        if os.path.islink(path) or not os.path.isfile(path):
            raise ManifestMismatch(f"{rel} is missing")
        if sha256(path) != digest:
            raise ManifestMismatch(f"{rel} doesn't match its checksum")
    for rel, target in manifest.get("links", {}).items():
        path = under(root, rel)
        if not os.path.islink(path) or os.readlink(path) != target:
            raise ManifestMismatch(f"{rel} should link to {target}")

files.archive/extract.py:
"""Unpacking a tar archive into a folder without letting it reach outside that folder.

Archives reach us from two places, plugin bundles (plugins/installer.py) and user backups (backups/restore.py), and
neither is trusted. safe_extract checks every member before it writes anything, so an archive it refuses leaves
the destination as it was.
"""
import os
import shutil
import stat
import tarfile

from . import limits, paths
from .errors import UnsafeArchive

FILE_MODE = 0o644
EXEC_MODE = 0o755
MAX_LINK_HOPS = 40  # how many links one path may pass through, as Linux's MAXSYMLINKS


def safe_extract(tar_path, dest):
    """Extract the tar at tar_path into the existing folder dest; return the member names, in archive order.

    Regular files, folders and symbolic links are extracted, and a link may point only inside dest. A member that
    would land outside dest, a link that points outside it, a name listed twice, any other kind of member or an
    archive over the size limits raises UnsafeArchive, and then nothing has been written. dest is assumed to be
    private to the caller while the archive is extracted."""
    root = os.path.realpath(dest)
    if not os.path.isdir(root):
        raise NotADirectoryError(dest)
    with tarfile.open(tar_path) as tar:
        members = tar.getmembers()
        limits.check(members)
        plan = plan_members(root, members)
        for member, name in plan:
            write_member(tar, member, os.path.join(root, *name.split("/")))
    return [paths.clean_name(m.name) for m in members]


def plan_members(root, members):
    """[(member, its clean name), ...] once every member has passed, or UnsafeArchive.

    Nothing is written until the whole archive has been checked as the folder will look once it is extracted: a
    link made by one member can send the path of a later member, or the target of another link, outside root."""
    entries = {}  # clean name -> ("folder" | "file" | "link", target parts for a link)
    plan = []
    for member in members:
        name = paths.clean_name(member.name)
        if name in entries:
            raise UnsafeArchive(f"{name} is listed twice")
        if member.issym():
            entries[name] = ("link", paths.link_parts(name, member.linkname))
        elif member.islnk():
            raise UnsafeArchive(f"{name} is a hard link")
        elif member.isdir():
            entries[name] = ("folder", None)
        elif member.isfile():
            entries[name] = ("file", None)
        else:
            raise UnsafeArchive(f"{name} is a device, a FIFO or another special file")
        plan.append((member, name))
    check_paths(root, entries)
    for name, (kind, target) in entries.items():
        if kind == "link":
            # A link is judged where it will lead once every link is in place, from the folder it sits in.
            resolve(root, entries, name, name.split("/")[:-1] + target)
    return plan


def check_paths(root, entries):
    """UnsafeArchive unless every member's path runs through folders only, and nothing already in root is in the way.
    Links already in root are refused too, since a member written through one would land wherever it points."""
    for name, (kind, _) in entries.items():
        parts = name.split("/")
        for i in range(1, len(parts) + 1):
            rel = "/".join(parts[:i])
            leaf = i == len(parts)
            if not leaf and entries.get(rel, ("folder",))[0] != "folder":
                raise UnsafeArchive(f"{name} is inside {rel}, which the archive makes something other than a folder")
            st = _lstat(root, rel)
            if st is None:
                continue
            if not leaf:
                if stat.S_ISLNK(st.st_mode):
                    raise UnsafeArchive(f"{name} would be written through {rel}, a link already in the folder")
                if not stat.S_ISDIR(st.st_mode):
                    raise UnsafeArchive(f"{name} is inside {rel}, which is not a folder")
            elif not (kind == "folder" and stat.S_ISDIR(st.st_mode)):
                raise UnsafeArchive(f"{name} is already in the folder")


def resolve(root, entries, name, parts):
    """The folder parts (names under root, ".." allowed) that the link called name leads to once the archive is out,
    following each link as it is then; UnsafeArchive if that climbs above root, passes through a link already in
    root, or loops."""
    out = []
    hops = 0
    pending = list(parts)
    while pending:
        part = pending.pop(0)
        if part in ("", "."):
            continue
        if part == "..":
            if not out:
                raise UnsafeArchive(f"{name} links to a path that climbs out of the folder")
            out.pop()
            continue
        rel = "/".join(out + [part])
        if rel in entries:
            if entries[rel][0] == "link":
                hops += 1
                if hops > MAX_LINK_HOPS:
                    raise UnsafeArchive(f"{name} is part of a loop of links")
                pending[:0] = entries[rel][1]
                continue
        else:
            st = _lstat(root, rel)
            if st is not None and stat.S_ISLNK(st.st_mode):
                raise UnsafeArchive(f"{name} goes through {rel}, a link already in the folder")
        out.append(part)
    return out


def write_member(tar, member, path):
    """Write one member, already checked, to path. Its parent folders exist or are made here; check_paths has shown
    that none of them is a link, so the writes stay where the plan put them."""
    if member.isdir():
        os.makedirs(path, exist_ok=True)
        return
    os.makedirs(os.path.dirname(path), exist_ok=True)
    if member.issym():
        os.symlink(member.linkname, path)
        return
    with tar.extractfile(member) as src, open(path, "xb") as out:
        shutil.copyfileobj(src, out)
    os.chmod(path, EXEC_MODE if member.mode & 0o100 else FILE_MODE)


def _lstat(root, rel):
    """lstat of rel under root, or None when nothing is there. Never follows a link."""
    try:
        return os.lstat(os.path.join(root, *rel.split("/")))
    except (FileNotFoundError, NotADirectoryError):
        return None

