"""Path rules for archive members. A member's name is a POSIX path relative to the archive's root."""
import os

from .errors import UnsafeArchive

MAX_NAME = 1024
MAX_HOPS = 40  # links followed while checking one link; a loop is refused rather than walked forever


def clean_name(name):
    """The member name as a relative path with no empty or "." parts. UnsafeArchive for an absolute name, a drive
    letter, a ".." part, a backslash or a NUL."""
    if not isinstance(name, str) or not name or "\x00" in name or "\\" in name:
        raise UnsafeArchive(f"bad member name {name!r}")
    if name.startswith("/") or (len(name) > 1 and name[1] == ":"):
        raise UnsafeArchive(f"{name} is an absolute path")
    parts = [part for part in name.split("/") if part not in ("", ".")]
    if not parts:
        raise UnsafeArchive(f"bad member name {name!r}")
    if ".." in parts:
        raise UnsafeArchive(f"{name} climbs out with ..")
    clean = "/".join(parts)
    if len(clean) > MAX_NAME:
        raise UnsafeArchive(f"a member name is longer than {MAX_NAME} characters")
    return clean


def check_link_target(linkname):
    """A link's target follows the same rules as a member name, except that it may hold "..". UnsafeArchive for an
    empty target, a NUL, a backslash, an absolute path or a drive letter. Whether it stays inside is stays_inside's
    job."""
    if not isinstance(linkname, str) or not linkname or "\x00" in linkname or "\\" in linkname:
        raise UnsafeArchive(f"bad link target {linkname!r}")
    if linkname.startswith("/") or (len(linkname) > 1 and linkname[1] == ":"):
        raise UnsafeArchive(f"link target {linkname} is an absolute path")


def stays_inside(name, linkname, link_at):
    """Whether the link called name, pointing at linkname, stays inside the destination once every link on the way
    is followed, the way the kernel follows them. Names are relative to the destination. link_at(rel) gives the
    target of the link at rel, or None when rel is not a link.

    The walk is physical, not lexical: a ".." that comes after a link climbs out of where that link points, so
    "d/s/.." with d/s -> .. leads to the folder above the destination. Dangling links are allowed if they stay in."""
    here = name.split("/")[:-1]  # the folder that holds the link
    pending = linkname.split("/")
    hops = 0
    while pending:
        part = pending.pop(0)
        if part in ("", "."):
            continue
        if part == "..":
            if not here:
                return False
            here.pop()
            continue
        here.append(part)
        target = link_at("/".join(here))
        if target is None:
            continue
        hops += 1
        if hops > MAX_HOPS or target.startswith("/"):
            return False
        here.pop()  # the link is replaced by its target, which is relative to the folder that holds it
        pending = target.split("/") + pending
    return True


def under(root, name):
    """The absolute path a member name maps to under root."""
    return os.path.join(root, *name.split("/"))

