            if not member.linkname or os.path.isabs(member.linkname) or "\x00" in member.linkname:
                raise UnsafeArchive(f"{name} links to an absolute path")
            seen[name] = ("link", member.linkname)
        elif member.islnk():
            raise UnsafeArchive(f"{name} is a hard link")
        elif member.isfile():
            seen[name] = ("file",)
        elif member.isdir():
            seen[name] = ("dir",)
        else:
            raise UnsafeArchive(f"{name} is a device, a FIFO or another special file")
        target = paths.under(root, name)
        if not paths.is_within(root, os.path.realpath(target)):
            raise UnsafeArchive(f"{name} would be written outside the destination")
        plan.append((member, target))
    # Every member is written at its plain path: no folder on the way may be a link or a file, whether it comes
    # from the archive (in any order) or is already in the destination, and nothing already there is replaced.
    parents = set()
    for name in seen:
        parts = name.split("/")
        for i in range(1, len(parts)):
            parent = "/".join(parts[:i])
            parents.add(parent)
            kind = seen.get(parent)
            if kind is not None and kind[0] != "dir":
                raise UnsafeArchive(f"{name} would be written through {parent}, which isn't a folder")
            if kind is None:
                path = paths.under(root, parent)
                if os.path.islink(path) or (os.path.lexists(path) and not os.path.isdir(path)):
                    raise UnsafeArchive(f"{name} would be written through {parent}, which isn't a folder")
        path = paths.under(root, name)
        if os.path.lexists(path) and not (seen[name][0] == "dir" and os.path.isdir(path)
                                          and not os.path.islink(path)):
            raise UnsafeArchive(f"{name} is already in the destination")
    # Every link must lead inside root in the tree as it will be, following other links (in the archive or
    # already in the destination) the way the OS does.
    for name, kind in seen.items():
        if kind[0] == "link":
            resolve(root, seen, parents, posixpath.dirname(name), kind[1], name)
    return plan


def _lookup(root, seen, parents, rel):
    kind = seen.get(rel)
    if kind is not None:
        return kind
    if rel in parents:
        return ("dir",)
    path = paths.under(root, rel)
    if os.path.islink(path):
        return ("link", os.readlink(path))
    if os.path.isdir(path):
        return ("dir",)
    if os.path.lexists(path):
        return ("file",)
    return None


def resolve(root, seen, parents, start, linkname, name):
    """UnsafeArchive unless linkname, read from folder start (relative to root), stays inside root."""
    cur = [p for p in start.split("/") if p]
    todo = linkname.split("/")
    hops = 0
    while todo:
        part = todo.pop(0)
        if part in ("", "."):
            continue
        if part == "..":
            if not cur:
                raise UnsafeArchive(f"{name} links to {linkname}, outside the destination")
            cur.pop()
            continue
        nxt = cur + [part]
        kind = _lookup(root, seen, parents, "/".join(nxt))
        if kind is not None and kind[0] == "link":
            hops += 1
            if hops > MAX_HOPS:
                raise UnsafeArchive(f"{name} links in a loop")
            target = kind[1]
            if os.path.isabs(target):
                real = os.path.normpath(target)
                if not paths.is_within(root, real):
                    raise UnsafeArchive(f"{name} links to {linkname}, outside the destination")
                cur = [p for p in os.path.relpath(real, root).split(os.sep) if p not in ("", ".")]
            todo = target.split("/") + todo if not os.path.isabs(target) else todo
            continue
        cur = nxt


def write_member(tar, member, target):
    if member.isdir():
        os.makedirs(target, exist_ok=True)
        return
    os.makedirs(os.path.dirname(target), exist_ok=True)
    if member.issym():
        os.symlink(member.linkname, target)
        return
    with tar.extractfile(member) as src, open(target, "xb") as out:
        shutil.copyfileobj(src, out)
    os.chmod(target, EXEC_MODE if member.mode & 0o100 else FILE_MODE)

"""Unpacking a tar archive into a folder without letting it reach outside that folder.

Archives reach us from two places, plugin bundles (plugins/installer.py) and user backups (backups/restore.py), and
neither is trusted. safe_extract checks every member before it writes anything, so an archive it refuses leaves
the destination as it was. The checks look at the destination as the whole archive will leave it (links followed
the way the kernel follows them), and the writes go through directory file descriptors without following links,
so what is written is what was checked.
"""
import os
import shutil
import stat
import tarfile

from . import limits, paths
from .errors import UnsafeArchive

FILE_MODE = 0o644
EXEC_MODE = 0o755
DIR_MODE = 0o755

DIR_FLAGS = os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW


def safe_extract(tar_path, dest):
    """Extract the tar at tar_path into the existing folder dest; return the member names, in archive order.

    Regular files, folders and symbolic links are extracted, and a link may point only inside dest. A member that
    would land outside dest or beneath a link, a link that leads outside it, a name listed twice, a name already
    in dest, any other kind of member or an archive over the size limits raises UnsafeArchive, and then nothing
    has been written. Modes are set by us (644, 755 for files marked executable, 755 for folders), never taken
    from the archive, and owners are never set."""
    root = os.path.realpath(dest)
    if not os.path.isdir(root):
        raise NotADirectoryError(dest)
    with tarfile.open(tar_path) as tar:
        members = tar.getmembers()
        limits.check(members)
        plan = plan_members(root, members)
        write_plan(tar, root, plan)
    return [name for name, _ in plan]


def plan_members(root, members):
    """[(clean name, member), ...] once every member has passed, or UnsafeArchive."""
    entries = {}
    for member in members:
        name = paths.clean_name(member.name)
        if name in entries:
            raise UnsafeArchive(f"{name} is listed twice")
        if member.issym():
            if not member.linkname:
                raise UnsafeArchive(f"{name} links to nothing")
        elif member.islnk():
            raise UnsafeArchive(f"{name} is a hard link")
        elif not (member.isfile() or member.isdir()):
            raise UnsafeArchive(f"{name} is a device, a FIFO or another special file")
        entries[name] = member

    def lookup(path):
        """(kind, linkname) of path in the destination as it will be after the archive is written."""
        member = entries.get(path)
        if member is not None:
            if member.issym():
                return "link", member.linkname
            return ("dir" if member.isdir() else "file"), None
        try:
            st = os.lstat(paths.under(root, path))
        except OSError:
            return None, None
        if stat.S_ISLNK(st.st_mode):
            return "link", os.readlink(paths.under(root, path))
        return ("dir" if stat.S_ISDIR(st.st_mode) else "file"), None

    for name, member in entries.items():
        parts = name.split("/")
        for i in range(1, len(parts)):
            kind, _ = lookup("/".join(parts[:i]))
            if kind == "link":
                raise UnsafeArchive(f"{name} would be written through the link {'/'.join(parts[:i])}")
            if kind == "file":
                raise UnsafeArchive(f"{name} would go inside {'/'.join(parts[:i])}, which isn't a folder")
        try:
            existing = os.lstat(paths.under(root, name))
        except OSError:
            existing = None
        if existing is not None and not (member.isdir() and stat.S_ISDIR(existing.st_mode)):
            raise UnsafeArchive(f"{name} is already in the destination")
    for name, member in entries.items():
        if member.issym():
            paths.resolve_link(lookup, name, member.linkname)
    return list(entries.items())


def open_dir(root_fd, parts, created):
    """A file descriptor for the folder at parts under root_fd, made where missing; no link is followed."""
    fd = os.dup(root_fd)
    try:
        for i, part in enumerate(parts):
            try:
                try:
                    new = os.open(part, DIR_FLAGS, dir_fd=fd)
                except FileNotFoundError:
                    os.mkdir(part, DIR_MODE, dir_fd=fd)
                    created.append((tuple(parts[:i + 1]), True))
                    new = os.open(part, DIR_FLAGS, dir_fd=fd)
                    os.fchmod(new, DIR_MODE)
            except OSError as e:
                raise UnsafeArchive(f"{'/'.join(parts[:i + 1])} isn't a folder we can write into: {e}") from None
            os.close(fd)
            fd = new
        return fd
    except BaseException:
        os.close(fd)
        raise


def write_plan(tar, root, plan):
    root_fd = os.open(root, DIR_FLAGS)
    created = []
    try:
        for name, member in plan:
            write_member(tar, root_fd, name, member, created)
    except BaseException:
        undo(root_fd, created)
        raise
    finally:
        os.close(root_fd)


def write_member(tar, root_fd, name, member, created):
    parts = name.split("/")
    if member.isdir():
        os.close(open_dir(root_fd, parts, created))
        return
    dir_fd = open_dir(root_fd, parts[:-1], created)
    try:
        leaf = parts[-1]
        if member.issym():
            os.symlink(member.linkname, leaf, dir_fd=dir_fd)
            created.append((tuple(parts), False))
            return
        fd = os.open(leaf, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600, dir_fd=dir_fd)
        created.append((tuple(parts), False))
        with os.fdopen(fd, "wb") as out, tar.extractfile(member) as src:
            shutil.copyfileobj(src, out)
            os.fchmod(out.fileno(), EXEC_MODE if member.mode & 0o100 else FILE_MODE)
    except FileExistsError:
        raise UnsafeArchive(f"{name} is already in the destination") from None
    finally:
        os.close(dir_fd)


def undo(root_fd, created):
    """Remove what this extraction made, newest first, so a failed one leaves the destination as it was."""
    for parts, is_dir in reversed(created):
        try:
            dir_fd = open_dir(root_fd, parts[:-1], [])
        except (OSError, UnsafeArchive):
            continue
        try:
            if is_dir:
                os.rmdir(parts[-1], dir_fd=dir_fd)
            else:
                os.unlink(parts[-1], dir_fd=dir_fd)
        except OSError:
            pass
        finally:
            os.close(dir_fd)

