"""Path rules for archive members. A member's name is a POSIX path relative to the archive's root."""
import os
import posixpath

from .errors import UnsafeArchive

MAX_NAME = 1024
MAX_PART = 255
MAX_LINK_HOPS = 40


def clean_name(name):
    """The member name as a relative path with no empty or "." parts. UnsafeArchive for an absolute name, a drive
    letter, a ".." part, a backslash or a NUL."""
    if not isinstance(name, str) or not name or "\x00" in name or "\\" in name:
        raise UnsafeArchive(f"bad member name {name!r}")
    if name.startswith("/") or (len(name) > 1 and name[1] == ":"):
        raise UnsafeArchive(f"{name} is an absolute path")
    parts = [part for part in name.split("/") if part not in ("", ".")]
    if not parts:
        raise UnsafeArchive(f"bad member name {name!r}")
    if ".." in parts:
        raise UnsafeArchive(f"{name} climbs out with ..")
    if any(len(part.encode("utf-8", "surrogateescape")) > MAX_PART for part in parts):
        raise UnsafeArchive(f"a part of {name[:80]!r} is longer than {MAX_PART} bytes")
    clean = "/".join(parts)
    if len(clean) > MAX_NAME:
        raise UnsafeArchive(f"a member name is longer than {MAX_NAME} characters")
    return clean


def is_within(root, path):
    """Whether path is root or under it; both absolute and normalized."""
    return path == root or path.startswith(root.rstrip(os.sep) + os.sep)


def link_target(root, name, linkname):
    """Where a link called name and pointing at linkname leads, as an absolute path, from the archive's names."""
    return os.path.normpath(os.path.join(root, posixpath.dirname(name), linkname))


def under(root, name):
    """The absolute path a member name maps to under root."""
    return os.path.join(root, *name.split("/"))


def resolve_link(lookup, name, linkname):
    """Where the link called name (a clean member name) leads, once every link on the way is followed, as a clean
    relative path under the destination: the way the kernel would walk it, not just by the names.

    lookup(path) is (kind, target) for a clean relative path, kind "link" (target is its linkname), "dir", "file"
    or None. It must describe the destination as it will be once the whole archive is written.

    UnsafeArchive when the walk climbs above the destination, meets an absolute link, or follows more than
    MAX_LINK_HOPS links (a loop)."""
    if not linkname or "\\" in linkname or "\x00" in linkname or linkname.startswith("/") or (
            len(linkname) > 1 and linkname[1] == ":"):
        raise UnsafeArchive(f"{name} links to {linkname!r}, which isn't a relative path")
    stack = name.split("/")[:-1]
    todo = linkname.split("/")[::-1]
    hops = 0
    while todo:
        part = todo.pop()
        if part in ("", "."):
            continue
        if part == "..":
            if not stack:
                raise UnsafeArchive(f"{name} links to {linkname}, outside the destination")
            stack.pop()
            continue
        stack.append(part)
        kind, target = lookup("/".join(stack))
        if kind == "link":
            hops += 1
            if hops > MAX_LINK_HOPS:
                raise UnsafeArchive(f"{name} links to {linkname}, through too many links")
            if not target or target.startswith("/") or "\\" in target:
                raise UnsafeArchive(f"{name} links to {linkname}, through a link to {target!r}")
            stack.pop()
            todo.extend(target.split("/")[::-1])
    return "/".join(stack)

